// === Tab: mySketch ===
/*
This is a test of p5.strands in p5.js 2.0! It's using a shader
to position a bunch of spheres on the GPU based off of the index
of the sphere (instanceID() in the shader code.)

See a tutorial on doing particles with a shader here:
https://beta.p5js.org/tutorials/intro-to-p5-strands/
*/

let shellShader
let env
let bump
let cam
p5.disableFriendlyErrors = true

let numLoops, rScale

async function setup() {
	createCanvas(windowWidth, windowWidth*.75, WEBGL)
	env = await loadImage('https://openprocessing.org/sketch/2665274/files/beach-small.jpeg')
	cam = createCamera()

	bump = buildGeometry(() => ellipsoid(8, 7, 6));//sphere(15, 10, 5))

	numLoops = random(2, 5)
	rScale = random(1, 3)

	shellShader = baseMaterialShader().modify(() => {
		// Try animating this!
		// const rScaleVal = uniformFloat(() => rScale + 0.5*sin(millis()*0.001))
		const rScaleVal = uniformFloat(() => rScale)
		const numLoopsVal = uniformFloat(() => numLoops)

		getObjectInputs((inputs) => {
			const pos = floor(float(instanceID()) / 10)
			const curveFrac = float(instanceID()) / 10 - pos
			const r = pow(pos / 250, rScaleVal) * 200

			const theta = pos / 250 * numLoopsVal * TWO_PI
			const angle = theta + PI / 2
			const curveAngle = curveFrac * -PI

			const nextAngle = theta + TWO_PI
			const nextPos = nextAngle / (numLoopsVal * TWO_PI / 250)
			const nextR = pow(nextPos / 250, rScaleVal) * 200
			const curveMag = (nextR - r) / 2

			const bumpScale = curveMag / 30

			const curveX = curveMag * cos(curveAngle)
			const curveY = curveMag * sin(curveAngle)
			const curveCos = cos(theta)
			const curveSin = sin(theta)

			const x = r * cos(theta)
			const y = r * sin(theta)
			inputs.position *= bumpScale
			inputs.position += [x, y, 0]
			inputs.position += [curveX * curveCos, curveX * curveSin, curveY]
			return inputs
		})
	})
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	panorama(env)
	imageLight(env)
	noStroke()

	var theta = millis() * 0.00007
	setCamera(cam)
	cam.setPosition(800*cos(theta), 0, 800*sin(theta))
	cam.lookAt(0,0,0)
	//orbitControl()

	push()
	directionalLight(100, 80, 50, 0, 0, -1)
	rotateY(millis() * 0.0005)
	rotateX(PI * 0.1)
	// rotateX(millis() * 0.0001)
	specularMaterial(100, 0, 0)
	shininess(3)
	shader(shellShader)
	scale(min(width/1400, height/1000))
	translate(0, -100, 0)
	model(bump, 5 * 500)
	pop()
	// model(shell)
}

function mouseClicked(){
   save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

